async function* createCommitMessage(sdk: ContinueSDK) {
  // @ts-expect-error
  const { execSync } = require('child_process')
  const [directory] = await sdk.ide.getWorkspaceDirs()
  let commitCommand = 'git commit --message'
  let diff = ''
  diff = execSync(`git -C ${directory} diff --staged`).toString()
  // If there are no staged changes, run git diff
  if (!diff.trim()) {
    // Alternatively: diff = await sdk.ide.getDiff()
    diff = execSync(`git -C ${directory} diff`).toString()
    commitCommand = 'git add . && git commit --message'
  }

  if (diff.trim()) {
    const commitMessage = await sdk.llm.complete(
      `${diff}\n\nPlease provide a brief, specific commit message (under 50 characters) about the changes above, using the Conventional Commits format: '<scope>: <message>'. Always include a scope. If the changes are only in markdown files, use 'docs' as the scope. Valid scopes include: build, ci, docs, feat, fix, perf, refactor, style, test, chore, revert, bump. If it's unclear, use 'chore' as the scope.`)
    await sdk.ide.runCommand(`${commitCommand} '${commitMessage}'`)
  }
  else {
    yield 'nothing to commit'
  }
}

export function modifyConfig(config: Config): Config {
  config.slashCommands?.push(
    {
      name: 'commit',
      description: 'Write a commit message',
      run: createCommitMessage,
